```python
import functools
import logging

def log_function_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        # Log the function call with arguments
        logging.info(f"Calling {func.__name__} with arguments: {args}, {kwargs}")

        # Call the original function with the arguments
        result = func(*args, **kwargs)

        # Log the return value if it's not None
        if result is not None:
            logging.info(f"Return value: {result}")

        return result

    return wrapper

